import "./skeleton.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type SkeletonProps = ComponentProps<"span">;

export function Skeleton({ className, ...rest }: SkeletonProps) {
  return (
    <span
      className={cx("ns-skeleton", className)}
      aria-hidden="true"
      {...rest}
    />
  );
}

@layer components {
  .ns-skeleton {
    display: block;
    min-height: 1em;
    border-radius: var(--radius, 0.4rem);
    background: var(--bg-well, #e8e6e4);
    box-shadow: var(--well);
    animation: ns-skeleton 1.2s ease-in-out infinite;
  }

  @keyframes ns-skeleton {
    50% {
      opacity: 0.55;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-skeleton {
      animation: none;
    }
  }
}
